INSERT INTO factory(id,code,name,timezone) VALUES ('00000000-0000-0000-0000-000000000001','AF-IND-01','AETHERFORGE SMART FACTORY — INDIA','Asia/Kolkata');
INSERT INTO production_line(factory_id,code,name,product) SELECT '00000000-0000-0000-0000-000000000001','L-'||i,'Production Line '||i,CASE (i%4) WHEN 0 THEN 'Servo Drive' WHEN 1 THEN 'Precision Motor' WHEN 2 THEN 'Industrial Pump' ELSE 'CNC Housing' END FROM generate_series(1,5) i;
INSERT INTO machine(factory_id,line_id,code,name,machine_type,status,health,failure_probability,rul_hours,last_maintenance) SELECT '00000000-0000-0000-0000-000000000001',pl.id,'M-'||lpad(((row_number() over())::int)::text,2,'0'),CASE WHEN ((row_number() over())::int)=7 THEN 'CNC-07' ELSE 'Machine '||((row_number() over())::int) END,CASE (((row_number() over())::int)%4) WHEN 0 THEN 'CNC' WHEN 1 THEN 'ROBOT' WHEN 2 THEN 'PRESS' ELSE 'INSPECTION' END,CASE WHEN ((row_number() over())::int)=7 THEN 'WARNING' ELSE 'RUNNING' END,CASE WHEN ((row_number() over())::int)=7 THEN 72 ELSE 92+(((row_number() over())::int)%7) END,CASE WHEN ((row_number() over())::int)=7 THEN .68 ELSE .03+(((row_number() over())::int)%5)*.01 END,CASE WHEN ((row_number() over())::int)=7 THEN 180 ELSE 1600+(((row_number() over())::int)%9)*120 END,now()-make_interval(days=>(10+((row_number() over())::int)%30)) FROM production_line pl CROSS JOIN generate_series(1,6) x LIMIT 30;
INSERT INTO sensor(machine_id,code,kind,unit) SELECT m.id,upper(left(s.kind,3))||'-'||right(m.code,2)||'-'||row_number() over(partition by m.id order by s.kind),s.kind,s.unit FROM machine m CROSS JOIN (VALUES ('Temperature','°C'),('Vibration','mm/s'),('Pressure','bar'),('RPM','rpm'),('Current','A'),('Voltage','V'),('Power','kW'),('Flow','L/min')) s(kind,unit);
INSERT INTO sensor_reading(sensor_id,recorded_at,value) SELECT s.id,now()-make_interval(mins=>g),CASE s.kind WHEN 'Temperature' THEN 52+(random()*7)+CASE WHEN m.code='M-07' THEN g*.18 ELSE 0 END WHEN 'Vibration' THEN 1.4+random()*.5+CASE WHEN m.code='M-07' THEN g*.025 ELSE 0 END WHEN 'Pressure' THEN 5.5+random()*.5 WHEN 'RPM' THEN 1400+random()*100 WHEN 'Current' THEN 18+random()*5 WHEN 'Voltage' THEN 400+random()*10 WHEN 'Power' THEN 12+random()*3 WHEN 'Flow' THEN 80+random()*8 END FROM sensor s JOIN machine m ON m.id=s.machine_id CROSS JOIN generate_series(0,59) g;
INSERT INTO production_metric(factory_id,line_id,recorded_at,target,actual,throughput,cycle_time,downtime_minutes,oee,quality,scrap) SELECT f.id,pl.id,now()-make_interval(hours=>g),1000,900+(random()*150)::int,160+(random()*40),22+random()*4,3+random()*8,.78+random()*.18,.94+random()*.05,8+(random()*6)::int FROM factory f JOIN production_line pl ON pl.factory_id=f.id CROSS JOIN generate_series(0,47) g;
INSERT INTO energy_metric(factory_id,machine_id,recorded_at,kwh,energy_per_unit,peak_kw,cost,baseline,anomaly) SELECT f.id,m.id,now()-make_interval(hours=>g),18+random()*8,.08+random()*.05,30+random()*5,(18+random()*8)*8.2,22,(m.code='M-07' and g<8) FROM factory f JOIN machine m ON m.factory_id=f.id CROSS JOIN generate_series(0,23) g;
INSERT INTO maintenance_record(factory_id,machine_id,status,priority,technician,scheduled_at,notes,ai_recommendation) SELECT f.id,m.id,CASE WHEN m.code='M-07' THEN 'OPEN' ELSE 'COMPLETED' END,CASE WHEN m.code='M-07' THEN 'HIGH' ELSE 'LOW' END,CASE WHEN m.code='M-07' THEN 'Priya Nair' ELSE 'Maintenance Team' END,now()+interval '4 hours',CASE WHEN m.code='M-07' THEN 'Bearing degradation follow-up' ELSE 'Preventive maintenance' END,CASE WHEN m.code='M-07' THEN 'Inspect spindle bearing and verify vibration after simulated intervention.' ELSE null END FROM factory f JOIN machine m ON m.factory_id=f.id;
INSERT INTO failure_prediction(machine_id,health_score,anomaly_score,failure_probability,rul_hours,risk_level,predicted_at,model_version,explanation) SELECT id,health,least(.98,1-health/100.0),failure_probability,rul_hours,CASE WHEN failure_probability>.7 THEN 'CRITICAL' WHEN failure_probability>.35 THEN 'HIGH' WHEN failure_probability>.15 THEN 'MEDIUM' ELSE 'LOW' END,now(),'aetherforge-synthetic-v1',CASE WHEN code='M-07' THEN 'Vibration and temperature are trending above baseline with elevated degradation risk.' ELSE 'Sensor values remain within expected operating envelope.' END FROM machine;
INSERT INTO alert(factory_id,machine_id,severity,status,description,evidence,recommendation) SELECT factory_id,id,'CRITICAL','OPEN','CNC-07 bearing degradation risk is elevated','Vibration trend + temperature rise + high predicted failure probability','Schedule bearing inspection and simulated maintenance.' FROM machine WHERE code='M-07';
INSERT INTO ai_recommendation(factory_id,machine_id,title,insight,evidence,confidence,recommended_action) SELECT factory_id,id,'CNC-07 maintenance window','Bearing degradation is the highest current operational risk.','Vibration trend is rising; temperature is above its machine baseline; maintenance is due.','.91','Create high-priority maintenance work order before next production window.' FROM machine WHERE code='M-07';
INSERT INTO autonomous_action(factory_id,machine_id,type,state,reason,risk,expected_outcome,evidence) SELECT factory_id,id,'CREATE_MAINTENANCE_WORK_ORDER','AWAITING_APPROVAL','Elevated bearing degradation risk','MEDIUM','Machine health should stabilize after simulated maintenance.','CNC-07 prediction + alert + sensor trend' FROM machine WHERE code='M-07';
